function check(input, actual, expected) {
  const [grid] = input;
  if (!Array.isArray(actual)) return false;
  if (expected.length === 0) return actual.length === 0;
  if (actual.length === 0) return false;
  for (let i = 0; i < actual.length; i++) {
    if (!Number.isInteger(actual[i]) || actual[i] < 0 || actual[i] >= grid.length) return false;
    if (i > 0 && actual[i] <= actual[i - 1]) return false;
  }
  const half = Math.floor(actual.length / 2);
  for (let j = 0; j < grid[0].length; j++) {
    let ones = 0;
    for (const row of actual) ones += grid[row][j];
    if (ones > half) return false;
  }
  return true;
}

