function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 10000) return 'grid needs 1 to 10^4 rows.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1 || n > 5) return 'Each row has 1 to 5 columns.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row must have the same length.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Every cell is 0 or 1.';
  }
  return null;
}

