function goodSubsetofBinaryMatrix(grid) {
  const firstRow = new Map();

  for (let i = 0; i < grid.length; i++) {
    let mask = 0;
    for (let j = 0; j < grid[i].length; j++) {
      mask |= grid[i][j] << j;
    }
    if (mask === 0) {
      return [i];
    }
    if (!firstRow.has(mask)) {
      firstRow.set(mask, i);
    }
  }

  for (const [maskA, rowA] of firstRow) {
    for (const [maskB, rowB] of firstRow) {
      if ((maskA & maskB) === 0) {
        return [Math.min(rowA, rowB), Math.max(rowA, rowB)];
      }
    }
  }
  return [];
}

