function goodSubsetofBinaryMatrix(grid) {
  const m = grid.length;
  const n = grid[0].length;
  // Try every non-empty set of rows, smallest bit patterns first.
  for (let pick = 1; pick < (1 << m); pick++) {
    const rows = [];
    for (let r = 0; r < m; r++) if (pick & (1 << r)) rows.push(r);
    const half = Math.floor(rows.length / 2);
    let good = true;
    for (let c = 0; c < n && good; c++) {
      let ones = 0;
      for (const r of rows) ones += grid[r][c];
      if (ones > half) good = false;
    }
    if (good) return rows;
  }
  return [];
}

