function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const bits = (mask, n) => Array.from({ length: n }, (_, j) => (mask >> j) & 1);
  const popcount = mask => { let c = 0; while (mask) { c += mask & 1; mask >>= 1; } return c; };
  if (size === 'large') {
    const m = 2000;
    const mode = pick(0, 2);
    if (mode === 0) {
      // Every row has a 1 in column 0, so no two rows are disjoint: the answer is empty.
      const n = pick(1, 5);
      return [Array.from({ length: m }, () => bits(1 | (pick(0, (1 << n) - 1)), n))];
    }
    // Five columns and at least three ones per row: any two rows overlap...
    const heavy = [];
    for (let mask = 0; mask < 32; mask++) if (popcount(mask) >= 3) heavy.push(mask);
    const grid = Array.from({ length: m }, () => bits(heavy[pick(0, heavy.length - 1)], 5));
    if (mode === 2) {
      // ...unless one late row is a light mask disjoint from some earlier row.
      const partner = grid[pick(0, m - 1)].reduce((acc, v, j) => acc | (v << j), 0);
      const free = 31 & ~partner;
      const light = free & -free;
      grid[pick(m - 50, m - 1)] = bits(light, 5);
    }
    return [grid];
  }
  const m = pick(1, 8);
  const n = pick(1, 5);
  const density = [0.3, 0.6, 0.8, 0.95][pick(0, 3)];
  return [Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)))];
}
